// Computes the maximum value among the first `n` elements of `a`.
// Preconditions (as stated): 0 < n <= a.len(), and n < 1000.
fn max(a: &Vec<i32>, n: usize) -> i32 {
    let mut m = a[0]; // n > 0, so the prefix is non-empty.
    for i in 1..n {
        if a[i] > m {
            m = a[i];
        }
    }
    m
}

fn main() {
    // Example usage
    let a = vec![3, -1, 7, 2, 7, 0];
    let n = 4; // only consider [3, -1, 7, 2]
    let ans = max(&a, n);
    println!("{ans}"); // prints 7
}